const $=id=>document.getElementById(id),S='francoise-namibia-journey-v1';let saved={};try{saved=JSON.parse(localStorage.getItem(S)||'{}')}catch{};let results=saved.results||{};const sections=[['discover','Discover Windhoek'],['dates','Choose your dates'],['plan','Plan the trip'],['airport','Leave France'],['arrival','Arrive in Namibia'],['hotel','Choose your hotel'],['explore','Explore Windhoek'],['review','Your travel challenge'],['pronunciation','Pronunciation'],['conservation','Conservation']];$('nav').innerHTML=sections.map((s,i)=>`<a href="#${s[0]}">${String(i+1).padStart(2,'0')} · ${s[1]}</a>`).join('');function section(id,number,title,desc,body){return `<section id="${id}"><div class="eyebrow">CHAPTER ${number} / 10</div><h2>${title}</h2><p class="intro">${desc}</p>${body}</section>`}function photo(title,description,img,url){return `<article class="card"><img src="${img}" alt="Illustrative travel photograph for ${title}" loading="lazy"><div class="inside"><h3>${title}</h3><p>${description}</p>${url?`<a href="${url}" target="_blank" rel="noopener">Explore location / official information ↗</a>`:''}</div></article>`}function rule(title,use,form,yes,no,question,keywords,exception){return `<div class="grammar"><div class="step">LEARN THE GRAMMAR BEFORE PRACTISING</div><h3>${title}</h3><p><b>When and why:</b> ${use}</p><p><b>Form:</b> ${form}</p><div class="forms"><b>✓ Affirmative:</b> ${yes}<br><b>− Negative:</b> ${no}<br><b>? Question:</b> ${question}</div><p><b>Keywords:</b> ${keywords}</p><p><b>Remember:</b> ${exception}</p></div>`}const exercises={};function quiz(id,question,answers,correct,explain,hint){exercises[id]={correct,explain,hint};let order=answers.map((x,i)=>({x,i}));if(id.length%2)order.reverse();else if(id.charCodeAt(id.length-1)%3===0)order.push(order.shift());return `<div class="quiz" data-quiz="${id}"><b>${question}</b><div class="choices">${order.map(a=>`<button type="button" data-choice="${a.i}">${a.x}</button>`).join('')}</div><div class="actions"><button class="secondary" data-hint="${id}">💡 Hint</button><button class="secondary" data-answer="${id}">✓ Show answer</button><button class="secondary" data-retry="${id}">↻ Try again</button></div><div class="feedback" aria-live="polite"></div></div>`}function practice(title,items){return `<div class="panel"><h3>${title}</h3>${items.map((x,i)=>quiz(title.replace(/\W/g,'').slice(0,12)+i,x[0],x[1],x[2],x[3],x[4])).join('')}</div>`}function openTask(id,title,prompt,clear,stretch,hint){return `<div class="task"><h3>🎤 ✍️ ${title}</h3><p>${prompt}</p><textarea id="${id}" placeholder="Write your answer here, then practise saying it aloud…"></textarea><div class="actions"><button data-open="${id}">Check structure</button><button class="secondary" data-openhint="${id}" data-msg="${hint}">Hint</button><button class="secondary" data-model="${id}">Clear / Stretch models</button><button class="secondary" data-speakfield="${id}">🔊 Listen to my text</button></div><div class="feedback" id="${id}Feedback"></div><div class="models" id="${id}Models"><b>Clear model (A2):</b> ${clear}\n\n<b>Stretch model (B1/B1+):</b> ${stretch}</div></div>`}function dialogue(lines){return `<div class="dialogue"><h3>Listen and act it out</h3><p>Click each line to listen. Then play the role of the traveller.</p>${lines.map(([who,line])=>`<div class="dialogueLine"><b>${who}</b><span>${line}</span><button data-speak="${encodeURIComponent(line)}">🔊 Listen</button></div>`).join('')}</div>`}const words=[['Planning & documents','passport','passeport','An official document used for international travel.','I need to check my passport.'],['Planning & documents','travel insurance','assurance voyage','Cover for certain unexpected travel costs.','I am going to compare travel insurance.'],['Planning & documents','entry requirements','conditions d’entrée','Rules you must satisfy to enter a country.','What are the entry requirements?'],['Planning & documents','visa','autorisation électronique de voyage','An entry document that may be required depending on your nationality and the current rules.','Do I need a visa before travelling?'],['Dates & times','departure date','date de départ','The day you leave.','Our departure date is the twenty-third of June.'],['Dates & times','return date','date de retour','The day you come back.','We are returning on the fifth of July.'],['Dates & times','fortnight','quinzaine / deux semaines','A period of fourteen days.','We are staying for a fortnight.'],['Dates & times','quarter past','et quart','Fifteen minutes after the hour.','The shuttle leaves at quarter past eight.'],['Airport & flights','boarding pass','carte d’embarquement','Document used to board an aircraft.','Could you show me your boarding pass?'],['Airport & flights','check-in desk','comptoir d’enregistrement','Place where you register for a flight.','Where is the check-in desk?'],['Airport & flights','connecting flight','vol avec correspondance','Another flight you take during your journey.','We have a connecting flight.'],['Airport & flights','baggage allowance','franchise bagages','The luggage permitted by the ticket.','What is my baggage allowance?'],['Airport & flights','security screening','contrôle de sécurité','Airport checks before boarding.','Where is security screening?'],['Airport & flights','gate','porte d’embarquement','The airport area where passengers board.','Which gate should we go to?'],['Transport','airport transfer','transfert aéroport','Transport between the airport and accommodation.','Is an airport transfer available?'],['Transport','ride-hailing app','application de VTC','App used to request a private ride.','Can I book a ride using an app?'],['Transport','shuttle bus','navette','Bus operating a particular route.','Does the hotel have a shuttle bus?'],['Transport','car rental','location de voiture','Hiring a vehicle for a period of time.','Is car rental available at the airport?'],['Transport','fare','tarif de transport','Amount paid for a journey.','How much is the fare?'],['Hotel & reception','reservation','réservation','A booking made in advance.','I have a reservation under Bernardini.'],['Hotel & reception','double room','chambre double','Room with a double bed.','I would like a double room.'],['Hotel & reception','check-in','enregistrement à l’hôtel','Process of registering on arrival.','What time is check-in?'],['Hotel & reception','breakfast included','petit-déjeuner compris','Breakfast is part of the rate.','Is breakfast included?'],['Hotel & reception','quiet room','chambre calme','Room away from noise.','Could I have a quiet room?'],['Exploring','wildlife','faune sauvage','Animals living in their natural habitats.','I would like to see wildlife.'],['Exploring','guided tour','visite guidée','Visit accompanied by a guide.','Are guided tours available?'],['Exploring','conservation','protection de la nature','Protecting habitats and species.','I am interested in conservation.'],['Exploring','craft market','marché artisanal','Market selling handmade items.','Where can I find a craft market?'],['Exploring','entrance fee','droit d’entrée','Price to enter an attraction.','What is the entrance fee?'],['Useful phrases','Could you repeat that?','Pourriez-vous répéter ?','A polite request to hear something again.','Could you repeat that more slowly?'],['Useful phrases','How long does it take?','Combien de temps cela prend-il ?','Question about duration.','How long does it take to get to the hotel?'],['Useful phrases','I would like to…','Je voudrais…','Polite way to express a wish.','I would like to visit the museum.'],['Useful phrases','Could you recommend…?','Pourriez-vous recommander… ?','Request for advice.','Could you recommend a local restaurant?']];function vocab(cat){let arr=words.filter(w=>w[0]===cat);return `<details><summary>📚 Vocabulary · ${cat} (${arr.length} words)</summary><div class="inside"><div class="cards">${arr.map(w=>`<div class="vocabCard"><strong>${w[1]}</strong><p class="french">${w[2]}</p><p>${w[3]}</p><p><i>${w[4]}</i></p><button data-speak="${encodeURIComponent(w[1]+'. '+w[4])}">🔊 Listen</button></div>`).join('')}</div></div></details>`}function stage(n,title,scene,body){return `<article class="journey-stage"><div class="stage-number">STEP ${n}</div><h3>${title}</h3><p class="scene">${scene}</p>${body}</article>`}function languageBox(title,terms){return `<div class="language-box"><h4>🧭 ${title}</h4><div class="termgrid">${terms.map(([a,b,c])=>`<div><b>${a}</b><span class="french">${b}</span><small>${c}</small><button data-speak="${encodeURIComponent(a+'. '+c)}">🔊 Listen</button></div>`).join('')}</div></div>`}function modelDialog(title,lines){return `<details class="model-dialog"><summary>🎭 ${title} · Open the complete model dialogue</summary>${dialogue(lines)}</details>`}function explainMini(title,when,positive,negative,question,important){return `<div class="grammar lesson-unit"><div class="step">EXPLAIN · MODEL · PRACTISE</div><h3>${title}</h3><p><b>When do we use it?</b> ${when}</p><div class="forms"><b>✓ Affirmative:</b> ${positive}<br><b>− Negative:</b> ${negative}<br><b>? Question:</b> ${question}</div><p><b>Watch out:</b> ${important}</p></div>`}
const gGoing=rule('BE GOING TO · plans and intentions','Use for intentions or decisions, even if they are not yet booked.','subject + am/is/are + going to + base verb','I am going to visit Windhoek.','I am not going to drive.','Are you going to stay for a week?','next month, tomorrow, this summer','After “going to”, use the base verb: going to visit, not going to visiting.');const gArranged=rule('PRESENT CONTINUOUS · fixed future arrangements','Use for arrangements that have been organised, usually with a future date or time.','subject + am/is/are + verb-ing + future time','I am flying on 23 June.','I am not leaving on Monday.','Are you flying on Tuesday?','on Friday, next Tuesday, at 9 a.m.','Compare: I am going to book (intention); I am flying on Tuesday (arrangement). The present simple is common for published timetables.');const gSimple=rule('PRESENT SIMPLE · schedules and facts','Use for regular services, facts and published timetables.','subject + base verb (add -s for he/she/it); do/does for questions','The shuttle leaves at eight.','The hotel does not offer a shuttle.','Does the hotel offer breakfast?','usually, every day, at eight','After does or doesn’t use the base verb: Does it leave? Not “Does it leaves?”');const gPolite=rule('COULD / WOULD LIKE · polite requests','Use could + base verb for a polite request; would like + to + verb for a preference.','Could + subject + base verb? / would like + to + base verb','I would like to book a room.','I would not like a noisy room.','Could you confirm the reservation?','please, could, would like','Never say “Could you to help?”; say “Could you help?”');const gNow=rule('PRESENT CONTINUOUS · happening right now','Use the same am/is/are + -ing form to describe an action happening at this moment.','subject + am/is/are + verb-ing','I am waiting at reception.','The air conditioning is not working.','Are you checking the booking?','now, right now, at the moment','Stative verbs like know and want are normally not continuous: “I want”, not “I am wanting”.');const gPast=rule('PAST SIMPLE · your travel memories','Use for completed events at a finished time.','past verb; did not + base verb; Did + subject + base verb?','I visited the museum yesterday.','I did not rent a car.','Did you enjoy the tour?','yesterday, last week, on Monday','Irregular verbs: go → went, see → saw, take → took. After did use base verb.');let html='';html+=section('discover','01','Welcome to Windhoek','You are planning an imaginary trip to Namibia. First discover what Windhoek offers, learn how to describe the places, then decide what kind of traveller you want to be.',`<div class="panel scene-intro"><h3>🇳🇦 Where are we going?</h3><p><b>Windhoek</b> is Namibia’s capital and an important centre for culture, business and tourism in southern Africa. It is a gateway to desert landscapes, national parks and Atlantic coastal towns. Namibia is the <b>country</b>; Namibian is the <b>nationality</b>. The currency is the <b>Namibian dollar (NAD)</b>; the South African rand is also legal tender. People speak English and several indigenous languages, among other languages. In the following scenes, you will practise describing a destination, comparing interests and asking a local guide questions.</p><p><b>Before you start:</b> Say aloud: “I would love to visit Windhoek because…”</p></div><div class="cards">${photo('Windhoek · capital and culture','WHY GO? Discover Namibia’s capital, its markets, historic architecture and diverse cultures. GOOD FOR: learning about local life and starting a Namibian journey. DESCRIBE IT: welcoming, lively, multicultural, fascinating.','https://images.unsplash.com/photo-1611348586755-53860f7ae57a?w=900','https://visitnamibia.com.na/')}${photo('Etosha National Park · wildlife','WHY GO? Watch wildlife at waterholes in a famous protected savannah landscape. GOOD FOR: safaris and discussions about endangered animals and anti-poaching. DESCRIBE IT: vast, spectacular, wild, protected.','https://images.unsplash.com/photo-1516026672322-bc52d61a55d5?w=900','https://www.meft.gov.na/')}${photo('Sossusvlei · Namib Desert dunes','WHY GO? Discover enormous red dunes and striking desert landscapes around Deadvlei. GOOD FOR: nature photography and describing extraordinary scenery. DESCRIBE IT: breathtaking, arid, dramatic, unforgettable.','https://images.unsplash.com/photo-1547721064-da6cfb341d50?w=900','https://www.nwr.com.na/')}${photo('Swakopmund · Atlantic coast','WHY GO? Explore a coastal town between the Atlantic Ocean and the Namib Desert. GOOD FOR: culture, coastal scenery and discovering the contrast between sea and desert. DESCRIBE IT: coastal, refreshing, picturesque, distinctive.','https://images.unsplash.com/photo-1448375240586-882707db888b?w=900','https://visitnamibia.com.na/')}</div>${languageBox('Describe a destination · useful adjectives',[['vibrant','dynamique, plein de vie','Windhoek is a vibrant capital city.'],['bustling','animé, très actif','The city centre is bustling.'],['peaceful','paisible','the Namib Desert looks peaceful.'],['scenic','pittoresque','The park has scenic landscapes.'],['fascinating','fascinant','The conservation project is fascinating.'],['worth visiting','qui vaut le détour','The museum is worth visiting.'],['crowded','bondé','Some tourist attractions can be crowded.'],['protected','protégé','It is a protected natural area.']])}${vocab('Exploring')}${explainMini('Describing a place · be + adjective / there is / there are','Start with a simple description, then add a reason. Use there is for one thing and there are for several things.','Windhoek is vibrant. There is beautiful landscapes across the country.','The city is not quiet everywhere. There are not many empty streets in a busy district.','Is Windhoek lively? Are there interesting places to visit?','Adjectives do not take plural -s: beautiful parks, not beautifuls parks. Use because to explain your choice.')}${practice('Discover Windhoek · vocabulary and descriptions',[['Choose the best meaning of vibrant.',['full of life','very empty','extremely cold'],0,'Vibrant means lively and full of energy.','Imagine a lively city with activities.'],['A forest is a good place for a ___ walk.',['peaceful','bustling','crowded'],0,'Peaceful describes a relaxing natural setting.','Think about quiet surroundings.'],['Choose the correct description.',['There are a national park.','There is a national park.','There be a national park.'],1,'There is + singular noun.','A national park is singular.'],['Which adjective describes a place with many people?',['crowded','protected','tranquil'],0,'Crowded = full of people.','A busy market can be…'],['Choose the correct sentence.',['The landscapes are scenics.','The landscapes is scenic.','The landscapes are scenic.'],2,'Adjectives never take a plural -s.','Plural landscapes + are.']])}${modelDialog('At the travel agency · before departure',[['Travel agent','You are planning a trip to Namibia. What kind of places would you like to discover?'],['You','I enjoy peaceful natural places, but I also love discovering local culture.'],['Travel agent','Would you prefer wildlife, desert landscapes or the Atlantic coast?'],['You','I would like to visit Etosha National Park because wildlife conservation fascinates me.'],['Travel agent','You might also enjoy the Namib Desert and Sossusvlei.'],['You','That sounds wonderful. What makes it special?']])}${openTask('interests','Your first travel conversation','Describe two Windhoek places using at least two adjectives and because. Then ask a guide one question.','Windhoek looks vibrant. I would like to visit the park because I love wildlife. Is there a guided tour?','Windhoek seems to combine a bustling city atmosphere with peaceful natural areas. I am particularly interested in conservation, so I would love to visit the Etosha National Park. Could you recommend a guided educational visit?','Begin with Windhoek looks / seems…, then I would like… because…, and finish with a question.')}`);html+=section('dates','02','Choose your dates and learn to say them','Your travel planner begins with the calendar. Select a departure and return date, then practise reading them aloud.',`${vocab('Dates & times')}<div class="panel"><h3>🌤️ When is the best time to visit Namibia?</h3><p><b>May to October</b> is generally the cooler, drier season and often ideal for viewing wildlife at Etosha waterholes. <b>June to August</b> can bring cold nights, especially inland. <b>November to April</b> is generally warmer and wetter in many regions, with greener landscapes and more birdlife; rainfall varies considerably by region. For desert sightseeing, consider temperature, sun exposure and early starts. Conditions and prices depend on the exact dates and location.</p><p><b>Travel-agent question:</b> When is the best time to visit Etosha National Park? <button data-speak="When%20is%20the%20best%20time%20to%20visit%20Etosha%20National%20Park%3F">🔊 Listen</button></p><p><b>Useful language:</b> dry season · rainy season · peak season · low season · cooler temperatures · wildlife viewing · sunrise · sunset · departure time.</p></div>${practice('Best season · choose and explain',[['Which season is usually best for wildlife viewing at Etosha?',['May to October','Only December','All months have identical conditions'],0,'The drier months often concentrate animals around waterholes.','Think about the dry season.'],['What should you pack for a June desert morning?',['Only swimwear','A warm layer','Nothing warm'],1,'Winter mornings and nights can be cold.','Desert nights can be chilly.'],['Ask the travel agent about the season.',['When is the best time to visit?','How many time visit?','What time best season?'],0,'When is the best time to visit? is a natural question.','Use When is the best time…?']])}${openTask('seasonTalk','Ask your travel agent about the best month','You have not left France yet. Ask about the best month, the weather and the best time of day to visit the dunes.','When is the best time to visit Namibia? Is it cold in July?','We are considering a trip in September. Would you recommend that month for wildlife viewing and desert excursions? What time should we leave to avoid the hottest part of the day?','Use When is…? Would you recommend…? What time…?')}<div class="panel"><div class="formgrid"><label>Departure date from France<input id="depart" type="date"></label><label>Return date<input id="return" type="date"></label><label>Travellers<input id="travellers" type="number" min="1" max="8" value="1"></label><label>Preferred departure time<select id="time"><option>Morning · 8:00 a.m.</option><option>Afternoon · 2:30 p.m.</option><option>Evening · 7:45 p.m.</option></select></label></div><div class="actions"><button id="datesBtn">Create my travel dates</button><button data-speakfield="dateOutput">🔊 Listen to my dates</button></div><div class="output" id="dateOutput">Choose your dates to begin.</div></div>${explainMini('1 · NUMBERS · How many? How much?','Cardinal numbers say how many people, bags, nights, euros or kilometres. 13 = thirteen, 30 = thirty; 14 = fourteen, 40 = forty. Use how many + plural countable noun, how much + price or uncountable noun.','There are two travellers. The room costs eighty euros.','There are not three suitcases. It does not cost ninety euros.','How many nights are you staying? How much does the ticket cost?','21–99 use a hyphen: twenty-one, thirty-five, ninety-nine. For 100: one hundred; 1,000: one thousand.')}${languageBox('Numbers worth learning',[['thirteen / thirty','treize / trente','Thirteen travellers. Thirty euros.'],['fifteen / fifty','quinze / cinquante','Fifteen minutes. Fifty kilometres.'],['eighteen / eighty','dix-huit / quatre-vingts','Eighteen seats. Eighty euros.'],['twenty-one','vingt et un','There are twenty-one seats.']])}${practice('Numbers · check immediately',[['A room costs €80. Say the price.',['eighteen euros','eighty euros','eight euros'],1,'80 = eighty; 18 = eighteen.','Look at the zero.'],['There are 13 passengers.',['thirty','thirteen','three'],1,'13 = thirteen, 30 = thirty.','-teen means 13–19.'],['Ask about a ticket price.',['How many does it cost?','How much does it cost?','How much tickets?'],1,'How much for price.','You want the price, not a count.'],['I have ___ suitcases.',['twenty-one','twenty-ones','twenty first'],0,'Cardinal twenty-one has no extra -s.','It is a quantity, not a date.']])}${openTask('numbersSpeak','At the travel agency · speaking and writing','Say how many people are travelling, how many nights you would like to stay, and ask about the price.','Two people are travelling. We would like to stay for seven nights. How much does it cost?','There will be two travellers, and we are considering a ten-night stay. Could you tell me the total cost, including taxes and any additional fees?','Use How many for quantities, How much for prices.')}${explainMini('2 · ORDINALS · First, second, third…','Use ordinals to indicate position, order and the day of a month. They are different from cardinal numbers.','The first flight is at eight. My room is on the third floor.','The second flight is not available.','Is the meeting on the twenty-first?','Irregular: 1st first; 2nd second; 3rd third; 5th fifth; 8th eighth; 9th ninth; 12th twelfth. 11th, 12th, 13th all end in -th. 21st, 22nd, 23rd, 31st follow their last number.')}${languageBox('Ordinals to remember',[['first, second, third','premier, deuxième, troisième','The first stop is check-in.'],['fifth, eighth, ninth','cinquième, huitième, neuvième','Our room is on the eighth floor.'],['eleventh, twelfth, thirteenth','onzième, douzième, treizième','We leave on the twelfth.'],['twenty-first, twenty-second, twenty-third','vingt et unième, vingt-deuxième, vingt-troisième','My departure is on the twenty-third.']])}${practice('Ordinals · check immediately',[['12th is…',['twelveth','twelfth','twelve'],1,'12th is twelfth.','The spelling changes.'],['Which is correct for 22nd?',['twenty-twoth','twenty-second','twenty-two'],1,'22nd = twenty-second.','The last part behaves like second.'],['11th is…',['elevenst','eleventh','elevennd'],1,'11th takes -th, not -st.','11, 12 and 13 are exceptions.'],['The 3rd floor is the…',['third floor','three floor','threeth floor'],0,'Use an ordinal: third.','Position in order.']])}${openTask('ordinalsSpeak','Order the journey','Tell the story of the first, second and third stops at an airport.','First, I check in. Second, I go through security. Third, I find the gate.','The first stage is check-in, the second is security screening, and the third is locating the departure gate and checking the boarding information.','First / Second / Third are signposting words too.')}${explainMini('3 · DATES · Say and write the day','Use an ordinal for the day. UK English often says “the twenty-third of June”; US English usually says “June twenty-third”. Both are correct spoken forms.','UK: I leave on the twenty-third of June. US: I leave on June twenty-third.','I am not leaving on the fifth of May.','What date are you leaving? Is your trip on July fourth?','Use on + date/day, in + month/year: on 23 June, in June, in 2027. The date formats 06/07 can be ambiguous; spell out the month.')}${practice('Dates · check immediately',[['UK: 23 June',['the twenty-three of June','the twenty-third of June','June twenty-three'],1,'In UK spoken English use the + ordinal + of + month.','23rd = twenty-third.'],['We are travelling ___ July.',['at','in','on'],1,'Use in with months.','in June, in July.'],['We are leaving ___ Monday.',['in','on','at'],1,'Use on for days.','On Monday.'],['Which written date avoids US/UK confusion?',['06/07','7 June 2027','07/06'],1,'Writing the month as a word makes the date clear.','Avoid numbers-only dates.']])}${openTask('dateRole','Date confirmation · role-play','You are speaking to a travel agent. Give a departure date and ask them to repeat the return date.','I would like to leave on the twenty-third of June. Could you repeat the return date, please?','I am considering departure on the twenty-third of June and a return in early July. Would you mind confirming the exact return date in writing?','Use on + date; Could you repeat…?')}${explainMini('4 · TIME · Flights, transfers and appointments','Use at + time. 8:00 = eight o’clock; 8:15 = quarter past eight / eight fifteen; 8:30 = half past eight / eight thirty; 8:45 = quarter to nine / eight forty-five. In 24-hour time, 14:30 is 2:30 p.m.','The flight leaves at nine o’clock. It departs at half past two in the afternoon.','The tour does not start at eight.','What time does the bus leave? Does the tour start at quarter past nine?','a.m. = before noon; p.m. = after noon. 12 p.m. = noon; 12 a.m. = midnight. Use “quarter to” the next hour for :45.')}${practice('Time · check immediately',[['8:15 is…',['quarter to eight','quarter past eight','half past eight'],1,'8:15 = quarter past eight.','15 minutes after eight.'],['7:45 is…',['quarter to eight','quarter past seven','half past seven'],0,'7:45 = quarter to eight.','15 minutes before eight.'],['14:30 is…',['two thirty p.m.','four thirty a.m.','half past fourteen a.m.'],0,'14:30 = 2:30 p.m.','Subtract twelve for afternoon hours after 12.'],['Choose the correct preposition.',['The shuttle leaves on 9:00.','The shuttle leaves in 9:00.','The shuttle leaves at 9:00.'],2,'Use at for a specific clock time.','At + time.']])}${openTask('timeRole','Ask about a transfer','Ask when a shuttle departs, then repeat the departure time and meeting place.','What time does the shuttle leave? It leaves at quarter past eight. Where do we meet?','Could you confirm the shuttle departure time and meeting point? I understand that it leaves at 8:15 a.m., and I would appreciate written confirmation.','What time…? It leaves at… Where…?')}${openTask('datesSpeak','Explain your plan','Tell a travel agent when you want to go, how long you will stay and what you are going to do.','I am going to travel in June. I am going to stay for one week.','I am planning a trip to Namibia, and I am going to spend several days in Windhoek before exploring the surrounding area.','Use going to + base verb and a date or duration.')}`);html+=section('plan','03','Build your dream itinerary','Decide how you would like to travel and stay. You are creating a practice itinerary, not buying tickets.',`${vocab('Planning & documents')}${stage('01','Decide your intentions','Nothing has been booked yet. What do you want to do in Namibia?',`${gGoing}${practice('Going to · plans before booking',[['I ___ visit Windhoek.',['am going to','is going to','going'],0,'With I use am going to + base verb.','I am…'],['We are going to ___ a hotel.',['booking','book','booked'],1,'After going to use the base verb.','No -ing after to here.'],['___ you going to travel in June?',['Do','Are','Did'],1,'Question: Are you going to + verb?','Invert be and subject.'],['She ___ going to rent a car.',['are not','is not','do not'],1,'She is not going to…','Use is with she.'],['The correct plan is…',['I am going to visiting the museum.','I am going visit the museum.','I am going to visit the museum.'],2,'Going to + base verb visit.','The verb after to has no -ing.']])}${openTask('intentionSpeak','Before you book · explain your ideas','Tell a friend three things you are going to do in Windhoek. Nothing has been confirmed yet.','I am going to visit Windhoek. I am going to see the wildlife. I am not going to rent a car.','I am going to explore Windhoek’s cultural attractions, and I am planning to learn more about conservation. I am not going to commit to any tours until I have checked the options.','I am going to + base verb; I am not going to + base verb.')}`)}<div class="panel"><div class="formgrid"><label>Departure airport in France<select id="origin"><option>Paris Charles de Gaulle (CDG)</option><option>Nantes Atlantique (NTE) · check connecting flights</option><option>Paris Orly (ORY) · check connecting flights</option></select></label><label>Arrival airport<select id="destination"><option>Jomo Namibiatta International Airport (WDH)</option></select></label><label>Flight preference<select id="flight"><option>Prefer a direct flight if available</option><option>Connecting flight is fine</option><option>Compare schedules and travel time</option></select></label><label>Accommodation style<select id="stay"><option>Comfortable city hotel</option><option>Small guesthouse</option><option>Eco-friendly lodge</option><option>Hotel near a national park</option></select></label><label>Top priority<select id="priority"><option>Wildlife and conservation</option><option>Culture and museums</option><option>Nature and walking</option><option>Food and local markets</option></select></label><label>Budget style<select id="budget"><option>Budget-conscious</option><option>Mid-range</option><option>Comfort first</option></select></label></div><div class="actions"><button id="planBtn">Create my itinerary</button></div><div class="output" id="planOutput">Your itinerary will appear here.</div></div><p><b>Real-world planning:</b> For international flights to Windhoek, look for <b>WDH (Jomo Namibiatta International Airport)</b>. <b>Eros Airport (ERS)</b> is a separate airport commonly associated with domestic and safari flights. Compare current routes on airline websites. Check passport validity, Namibia’s current entry/visa rules, health guidance, insurance and airport transfers before travel.</p><p><a href="https://visitnamibia.com.na/" target="_blank" rel="noopener">Namibia official tourism information</a> · <a href="https://www.diplomatie.gouv.fr/fr/conseils-aux-voyageurs/" target="_blank" rel="noopener">France Diplomatie · Conseils aux voyageurs</a> · <a href="https://www.parisaeroport.fr/" target="_blank" rel="noopener">Paris airports</a></p>${stage('02','Now your tickets are confirmed','You have chosen a flight and the airline has sent confirmation. What changed?',`${gArranged}${practice('Present continuous · real arrangements',[['My flight is booked. I ___ on Friday.',['am flying','flew','fly yesterday'],0,'Am flying is a future arrangement with a date.','am + verb-ing'],['We ___ on Monday; the tickets are confirmed.',['are leaving','left yesterday','are leave'],0,'Are leaving is an organised future arrangement.','are + verb-ing'],['___ you staying for five nights?',['Do','Are','Did'],1,'Are you staying…?','Start with Are.'],['She ___ meeting her guide tomorrow.',['are','is','does'],1,'She is meeting…','She + is.'],['Choose the future arrangement.',['I am going to look at flights tonight.','I am flying to Windhoek on a confirmed flight next Friday.','I fly yesterday.'],1,'The fixed flight makes this an arrangement.','Look for booked/confirmed details.']])}${openTask('arrangementSpeak','The confirmation email','You have booked your flight. Tell a friend when you are leaving and returning.','I am flying to Windhoek on Friday. I am returning the following Sunday.','My flight to Windhoek is confirmed for Friday morning, and I am returning the following Sunday. I am meeting a driver at the airport when I arrive.','Use am / are + -ing + a future time.')}`)}${stage('03','Choose the correct future form','You planned a safari last week. Today your ticket and guided visit have been confirmed. Compare an intention with an arranged event.',`<div class="contrast-grid"><div><b>INTENTION · BE GOING TO</b><p>I am going to visit a museum.<br><small>It is my plan. It may not be booked.</small></p></div><div><b>ARRANGEMENT · PRESENT CONTINUOUS</b><p>I am visiting the museum with my guide on Tuesday at 10 a.m.<br><small>The guide and time are arranged.</small></p></div><div><b>TIMETABLE · PRESENT SIMPLE</b><p>The flight departs at 9 a.m.<br><small>This is a published schedule.</small></p></div></div><p><b>Important nuance:</b> be going to and present continuous can both be natural for future plans. The key distinction in this lesson is <b>intention</b> versus <b>organised arrangement</b>; context matters more than a single keyword.</p>${practice('Future forms · decide from the situation',[['You are thinking about travel; nothing is booked.',['I am going to compare flights.','I am comparing a confirmed flight at 9 tomorrow.','I compared a flight yesterday.'],0,'Going to is natural for an intention.','Not booked yet.'],['You have booked a meeting with your guide for Tuesday.',['I am going to maybe call a guide.','I am meeting my guide on Tuesday.','I meet my guide yesterday.'],1,'Present continuous highlights a fixed arrangement.','The time and guide are confirmed.'],['The airline timetable says 8:30.',['The plane leaves at 8:30.','The plane is going to leaving at 8:30.','The plane leave at 8:30.'],0,'Published schedules often use the present simple.','A timetable is a schedule.'],['Choose the correct negative of an intention.',['I am not going to rent a car.','I do not going to rent a car.','I am not going renting a car.'],0,'Negative: am not + going to + base verb.','am not going to…'],['Choose the correct question about a confirmed meeting.',['Are you meeting the guide tomorrow?','Do you meeting the guide tomorrow?','Are you meet the guide tomorrow?'],0,'Are + you + meeting…?','Use are + -ing.']])}${modelDialog('Planning and booking with a friend',[['Friend','What are you going to do in Windhoek?'],['You','I am going to learn about wildlife conservation.'],['Friend','Have you organised any visits yet?'],['You','Yes. I am visiting the Etosha National Park with a guide on Tuesday morning.'],['Friend','What time does your flight leave?'],['You','The flight departs at 9:00 a.m.']])}${openTask('compareSpeak','Explain a plan, an arrangement and a timetable','Write three different sentences: an unbooked intention, a confirmed arrangement, and a published time. Explain the difference aloud.','I am going to visit a museum. I am meeting my guide on Tuesday. The plane leaves at nine.','I am going to explore local heritage because it interests me. I am meeting a guide on Tuesday at ten; we arranged it yesterday. According to the flight schedule, my plane departs at nine.','Plan: going to. Booked: am/is/are + ing. Timetable: present simple.')}`)}${openTask('planSpeak','Talk to a travel agent','Explain your flight preference, your hotel style and your plans.','I am flying to Windhoek. I would like a comfortable hotel.','I am arranging a visit to Windhoek and would prefer accommodation with convenient transport links, as I am hoping to explore several cultural and natural attractions.','Use am flying / am staying for confirmed arrangements and would like for preferences.')}`);html+=section('airport','04','Travel day · from France to Windhoek','Follow the real order of a journey. At every stage, learn a small group of words, practise a question, and act out a conversation before moving on.',`${vocab('Airport & flights')}${stage('01','Prepare at home','Your flight is tomorrow. You check your passport, travel documents, luggage allowance and flight details. Check any actual entry requirements on official websites before a real journey.',`${languageBox('Before leaving home',[['passport','passeport','My passport is in my bag.'],['booking confirmation','confirmation de réservation','I have my booking confirmation.'],['baggage allowance','franchise bagages','What is my baggage allowance?'],['departure terminal','terminal de départ','Which terminal do I need?']])}${practice('Packing your documents',[['You need to identify yourself internationally.',['passport','hotel key','receipt'],0,'You usually need your passport for international travel.','It proves identity.'],['Ask about permitted luggage.',['What is my baggage allowance?','What my baggage allowance?','How many allowance?'],0,'What is my baggage allowance?','Use What is…?']])}${openTask('packingSpeak','Tell your travel companion you are ready','Explain what you have packed and what you still need to check.','I have my passport and booking confirmation. I need to check the baggage allowance.','I have prepared my documents and packed my suitcase. Before leaving, I still need to check the terminal, baggage restrictions and current travel requirements.','I have… / I need to…')}`)}${stage('02','Travel to the departure airport','You leave home and travel to the airport with enough time for your flight. In this simulation, you arrive at the departures hall.',`${explainMini('PRESENT SIMPLE · departure schedules','Published departure times use the present simple.','The train leaves at 7:10. The flight departs at 10:30.','The shuttle does not leave at eight.','What time does the train leave? Does the flight depart at ten?','Use does + base verb, not “Does the flight departs?”')}${practice('Schedules and airport directions',[['The train ___ at seven.',['leave','leaves','leaving'],1,'The train leaves (third-person singular).','One train: it.'],['Does your flight ___ at eleven?',['departs','depart','departing'],1,'After does use base verb.','Does + depart.'],['Which sign do you follow first?',['Departures','Baggage reclaim','Arrivals'],0,'Departures is where you begin an outbound flight.','You are leaving France.']])}${modelDialog('At the airport information point',[['You','Excuse me. Where is the departures hall?'],['Staff','Go straight ahead and follow the departures signs.'],['You','Thank you. Which terminal is my flight leaving from?'],['Staff','Please check your airline and flight number on the screen.']])}`)}${stage('03','Find the check-in desk and drop your bag','First read the departures screen. Then find the correct airline desk. Show your passport and booking reference. If you have a checked bag, place it on the scale. Baggage procedures vary by airline.',`${languageBox('At check-in',[['check-in desk','comptoir d’enregistrement','Where is the check-in desk?'],['checked baggage','bagage en soute','I have one checked bag.'],['boarding pass','carte d’embarquement','Here is my boarding pass.'],['window seat','siège côté hublot','Could I have a window seat?']])}${modelDialog('Complete check-in dialogue',[['Airline agent','Good morning. May I see your passport and booking confirmation?'],['You','Of course. Here they are.'],['Airline agent','Are you checking in any bags?'],['You','Yes, one suitcase. Is it within the baggage allowance?'],['Airline agent','Yes. Here is your boarding pass.'],['You','Thank you. Could you tell me where security is?']])}${practice('Check-in · what do you say?', [['The agent asks for your passport.',['Here it is.','Here are it.','It here is.'],0,'Here it is.','Polite response when handing over one item.'],['You have a suitcase for the hold.',['I am checking in one suitcase.','I checking one suitcase.','I am check suitcase.'],0,'I am checking in one suitcase.','am + checking in.'],['Ask for a window seat.',['Could I have a window seat, please?','Could I to have a window seat?','Can I having a window seat?'],0,'Could + base verb have.','Could I have…?']])}${openTask('checkinSpeak','You are the passenger','Complete a check-in exchange: greeting, passport, luggage, seat preference, and a question about security.','Good morning. Here is my passport. I have one suitcase. Could I have a window seat? Where is security?','Good morning. Here are my passport and booking confirmation. I would like to check in one suitcase, and I was wondering whether a window seat is available. Could you direct me to security screening?','Five moves: greet → document → suitcase → seat → direction.')}`)}${stage('04','Go through security screening','Before reaching the departure gate, you follow the airport’s security instructions. Put your belongings in the trays as directed. Rules about liquids and electronics may vary by airport.',`${languageBox('At security',[['security screening','contrôle de sécurité','Where is security screening?'],['tray','bac','Please place your bag in the tray.'],['liquids','liquides','What are the rules for liquids?'],['remove','retirer','Do I need to remove my jacket?']])}${modelDialog('Security instructions',[['Officer','Please place your bag in the tray.'],['You','Of course. Should I take out my laptop?'],['Officer','Please follow the instructions on the sign.'],['You','Thank you. Do I need to remove my jacket?']])}${practice('Security · understand the instructions',[['The officer says “Place your bag in the tray.” You…',['put it in a tray','go to baggage reclaim','board the plane'],0,'Tray means bac.','Security comes before boarding.'],['Ask if you must remove your jacket.',['Do I need to remove my jacket?','Am I need remove jacket?','Do I must removing it?'],0,'Do I need to + base verb.','Do I need to…?']])}`)}${stage('05','Find your gate and board the plane','After security, look at the departure screens for your gate and possible changes. At boarding, follow the airline’s announcements, have your boarding pass ready and go to your seat.',`${languageBox('At the gate',[['departure board','tableau des départs','Check the departure board.'],['gate','porte d’embarquement','Our gate is B12.'],['boarding','embarquement','Boarding has started.'],['delayed','retardé','The flight is delayed.']])}${modelDialog('At the boarding gate',[['You','Excuse me. Is this the gate for the flight to Windhoek?'],['Agent','Please check your flight number on the screen.'],['You','Thank you. Has boarding started?'],['Agent','Yes. Please have your boarding pass ready.'],['You','Here it is. Thank you.']])}${practice('Boarding · correct order',[['What should you check after security?',['the departure screen and gate','the hotel reception','baggage reclaim'],0,'Your next stop is the departure gate.','You have not flown yet.'],['The flight is delayed. It is…',['earlier than planned','later than planned','cancelled automatically'],1,'Delayed means later than planned.','A delay is not automatically a cancellation.'],['What do you show when boarding?',['boarding pass','hotel receipt','bus ticket'],0,'Boarding pass = carte d’embarquement.','It says boarding.']])}${openTask('boardingSpeak','Ask about a delayed flight','The flight is delayed. Ask the airline agent for updated information and explain the situation to your travel companion.','Excuse me. Is the flight delayed? What time will boarding start?','Excuse me. I have noticed that the flight is delayed. Could you confirm the revised boarding time and let us know whether the departure gate has changed?','Ask: Could you confirm…? / Has the gate changed?')}`)}${stage('06','On board · ask the cabin crew','You have boarded. Find your seat, stow your hand luggage following crew instructions, and ask for help politely.',`${modelDialog('On the plane',[['Cabin crew','Welcome aboard. Can I help you?'],['You','Yes, please. Could you tell me where seat 18A is?'],['Cabin crew','It is further down on the left.'],['You','Thank you. Could I have some water later, please?'],['Cabin crew','Certainly.']])}${practice('On board · polite phrases',[['Ask for water politely.',['Could I have some water, please?','Could I to have water?','I want give water.'],0,'Could I have…?','Could + base verb.'],['Ask where your seat is.',['Where is seat 18A?','Where seat 18A is?','Where 18A be?'],0,'Where is + noun?','Direct questions invert subject and verb.']])}${openTask('flightSpeak','Cabin crew conversation','Ask where your seat is, request water politely and thank the crew.','Hello. Where is seat 18A, please? Could I have some water? Thank you.','Hello. Would you mind pointing me towards seat 18A? And when you have a moment, could I please have some water? Thank you very much for your assistance.','Where is…? / Could I have…? / Thank you.')}`)}`);html+=section('arrival','05','Welcome to Namibia · step by step','You have landed. Go through arrival formalities, collect your luggage, pass customs, and only then find transport to the hotel.',`${stage('01','Land and follow the arrivals signs','The plane lands at Jomo Namibiatta International Airport (WDH). Follow the arrivals signs and the instructions given by the airport.',`${languageBox('First words on arrival',[['arrivals','arrivées','Follow the arrivals signs.'],['passport control','contrôle des passeports','Where is passport control?'],['baggage reclaim','livraison des bagages','Where is baggage reclaim?'],['customs','douane','Which way is customs?']])}${practice('Arrival · find the next step',[['You have just landed. Which signs should you follow?',['Arrivals','Departures','Boarding'],0,'You follow arrivals signs.','You are entering Namibia.'],['Where are your travel documents usually checked?',['passport control','hotel reception','museum'],0,'Passport control concerns travel documents.','Look for passport.']])}`)}${stage('02','Passport or immigration control','You may be asked to show your passport and any required travel authorisation or supporting documents. Answer questions truthfully and clearly. Requirements depend on your nationality and current rules.',`${modelDialog('At passport control',[['Officer','Good afternoon. What is the purpose of your visit?'],['You','I am here for a holiday.'],['Officer','How long are you staying in Namibia?'],['You','I am staying for ten days.'],['Officer','Where are you staying?'],['You','I have booked a hotel in Windhoek.']])}${practice('Passport control · useful answers',[['Purpose of visit?',['I am here for a holiday.','I here for holidays am.','I am holiday here for.'],0,'I am here for a holiday.','State the reason.'],['How long are you staying?',['I am staying for ten days.','I staying at ten days.','I am stay ten days.'],0,'Am staying for + duration.','for + duration.']])}${openTask('immigrationSpeak','Answer an immigration officer','Say why you are visiting, how long you will stay and where you are staying.','I am here on holiday. I am staying for ten days at a hotel in Windhoek.','I am visiting Namibia for tourism. I plan to stay for approximately ten days, and I have a confirmed reservation at a hotel in Windhoek.','Purpose → duration → accommodation.')}`)}${stage('03','Collect your suitcase','After the relevant checks, follow the baggage reclaim signs. Find the carousel displayed for your flight and collect the correct bag. Exact airport procedures can vary.',`${modelDialog('Your suitcase is missing',[['You','Excuse me. My suitcase has not arrived.'],['Baggage agent','I am sorry. Do you have your baggage tag?'],['You','Yes, here it is. What should I do next?'],['Baggage agent','Please come to the baggage service desk.']])}${practice('At baggage reclaim',[['Where do you collect your checked suitcase?',['baggage reclaim','boarding gate','check-in desk'],0,'Baggage reclaim is after the flight.','You checked it in before departure.'],['Your luggage has not appeared.',['My suitcase has not arrived.','My suitcase not arrive has.','My suitcase have no arrived.'],0,'My suitcase has not arrived.','Use has + past participle.']])}${openTask('luggageSpeak','Report a missing suitcase','Ask the baggage agent for assistance and explain what your suitcase looks like.','Excuse me. My suitcase has not arrived. It is a large blue suitcase. Can you help me?','Excuse me. My checked suitcase has not appeared on the carousel. It is a medium-sized navy suitcase with a red luggage tag. Could you explain how to file a baggage report?','Say what happened → describe the suitcase → ask for help.')}`)}${stage('04','Go through customs and enter the arrivals hall','Follow customs instructions, declare items when required, and then continue to the public arrivals area. This is when you look for your pre-arranged transfer or another legitimate transport option.',`${modelDialog('Asking for the exit',[['You','Excuse me. Where is the arrivals exit, please?'],['Staff','Follow the signs to the arrivals hall.'],['You','Thank you. Where can I meet my pre-booked driver?'],['Staff','Please check the meeting instructions from your transfer company.']])}${practice('Customs and the meeting point',[['You need to follow the rules for goods entering the country.',['customs','check-in','boarding'],0,'Customs is about goods and declarations.','Different from passport control.'],['Ask where to meet your driver.',['Where can I meet my driver?','Where I can meet my driver?','Where meet can driver?'],0,'Question word + can + I + verb.','Where can I…?']])}`)}<div class="journey-bridge"><b>🚕 Next scene:</b> You have your suitcase and are in the arrivals hall. <b>Only now</b> do you arrange the journey to your hotel.</div>${vocab('Transport')}<div class="cards">${photo('Pre-arranged transfer','A driver meets you at the airport; useful when arriving late or with luggage.','https://images.unsplash.com/photo-1449965408869-eaa3f722e40d?w=900')}${photo('Taxi or app-based ride','Agree on the fare or verify the app price and vehicle details before leaving.','https://images.unsplash.com/photo-1519608487953-e999c86e7455?w=900')}${photo('Shuttle or bus','Compare routes, luggage rules, operating hours and safety before travelling.','https://images.unsplash.com/photo-1570125909232-eb263c188f7e?w=900')}${photo('Rent a car','Compare driving requirements and conditions; unfamiliar traffic can be challenging.','https://images.unsplash.com/photo-1503376780353-7e6692767b70?w=900')}</div><div class="panel"><label>How will you reach your hotel?<select id="transfer"><option>Pre-arranged hotel transfer</option><option>Licensed taxi</option><option>Ride-hailing app</option><option>Shuttle or bus</option><option>Rental car</option></select></label><div class="actions"><button id="transferBtn">Confirm my transport choice</button></div><div class="output" id="transferOutput">Choose your transport.</div></div>${gPolite}${dialogue([['You','Hello. I am going to a hotel in Windhoek.'],['Driver','Welcome! Do you have the address?'],['You','Yes. Could you confirm the fare before we leave?'],['Driver','Certainly. Would you like help with your luggage?'],['You','Yes, please. How long does the journey usually take?']])}${practice('Airport transfer · requests',[['___ you confirm the fare, please?',['Could','Could to','Are'],0,'Could + subject + base verb.','Use Could'],['I would like ___ a taxi.',['booking','to book','book'],1,'Would like + to + verb.','Would like TO…'],['How long ___ it take?',['does','is','do'],0,'How long does it take?','Use does with it.'],['We ___ to drive today.',['would not like','would not liking','not would like'],0,'Would not like + to + verb.','Would not like…']])}${openTask('taxiSpeak','Talk to your driver','Ask about the fare, travel time and where to put your luggage.','Could you confirm the fare, please?','Before we set off, would you mind confirming the estimated fare and journey time, and helping me with my suitcase?','Could you confirm…? How long does it take…?')}`);html+=section('hotel','06','Choose your Windhoek hotel','Compare three accommodation areas and practise booking and check-in. These are area-based choices, not live room offers.',`${vocab('Hotel & reception')}<div class="cards">${photo('Westlands','A lively area with restaurants and many accommodation options.','https://images.unsplash.com/photo-1566073771259-6a8506099945?w=900')}${photo('Karen','A greener, quieter-feeling area convenient for some nature and conservation visits.','https://images.unsplash.com/photo-1571896349842-33c89424de2d?w=900')}${photo('Central Windhoek','A practical base for some museums and city sightseeing; compare traffic and neighbourhood location.','https://images.unsplash.com/photo-1551882547-ff40c63fe5fa?w=900')}</div><div class="panel"><div class="formgrid"><label>Preferred area<select id="area"><option>Westlands</option><option>Karen</option><option>Central Windhoek</option></select></label><label>Room type<select id="room"><option>Double room</option><option>Twin room</option><option>Single room</option><option>Suite</option></select></label><label>Breakfast<select id="breakfast"><option>Breakfast included, if possible</option><option>Breakfast optional</option></select></label><label>Special request<input id="request" placeholder="A quiet room, please"></label></div><div class="actions"><button id="hotelBtn">Generate my hotel enquiry</button><button id="copyEnquiry">Copy enquiry</button></div><div class="output" id="hotelOutput">Your personalised enquiry will appear here.</div></div>${dialogue([['Receptionist','Good afternoon. Welcome to our hotel.'],['You','Hello. I have a reservation under my name.'],['Receptionist','May I see your passport and booking confirmation?'],['You','Of course. Is breakfast included?'],['Receptionist','Yes. Check-out is at eleven.'],['You','Thank you. Could you tell me where my room is?']])}${gNow}${practice('Hotel check-in · correct grammar',[['I ___ waiting at reception now.',['am','is','do'],0,'I am waiting.','I + am'],['The key card ___ working.',['does not','is not','not is'],1,'Is not working is present continuous.','is + not + -ing'],['___ the receptionist checking the booking?',['Does','Is','Do'],1,'Is + subject + verb-ing?','Is… checking?'],['Could you ___ the room number?',['confirm','to confirm','confirming'],0,'Could + base verb.','No to after could.']])}${openTask('hotelSpeak','Check in at reception','Introduce yourself, confirm your room and ask about breakfast and directions.','Hello. I have a reservation. Is breakfast included?','Good afternoon. I have a reservation under my name. Would you mind confirming the room type, breakfast arrangements and directions to my room?','Begin with “I have a reservation…” and ask two questions.')}`);html+=section('explore','07','Discover Windhoek, one day at a time','Your first sightseeing day! Compare attractions, ask for information and plan a conversation with a guide.',`<div class="cards">${photo('Windhoek National Museum','Discover Namibia’s natural history, culture and heritage.','https://images.unsplash.com/photo-1561214115-f2f134cc4912?w=900','https://visitnamibia.com.na/')}${photo('Etosha National Park','Discuss wildlife, guided visits, opening hours and conservation.','https://images.unsplash.com/photo-1534177616072-ef7dc120449d?w=900','https://www.meft.gov.na/')}${photo('Etosha National Park','Ask about educational visits and protecting giraffes.','https://images.unsplash.com/photo-1547721064-da6cfb341d50?w=900','https://www.nwr.com.na/')}${photo('the Namib Desert','Explore walking routes and responsible nature tourism.','https://images.unsplash.com/photo-1448375240586-882707db888b?w=900','https://visitnamibia.com.na/')}</div><div class="panel"><label>Choose your first attraction<select id="attraction"><option>Windhoek National Museum</option><option>Etosha National Park</option><option>Etosha National Park</option><option>the Namib Desert</option></select></label><div class="actions"><button id="attractionBtn">Plan my day</button></div><div class="output" id="attractionOutput">Choose an attraction.</div></div>${dialogue([['You','Good morning. Are guided tours available today?'],['Guide','Yes. What would you like to learn about?'],['You','I am interested in wildlife conservation.'],['Guide','Would you prefer a morning or afternoon visit?'],['You','A morning visit, please. How much is the entrance fee?']])}${gPast}${practice('Travel memories · past simple',[['Yesterday I ___ the museum.',['visit','visited','visiting'],1,'Finished event: visited.','Use past form.'],['We ___ a giraffe.',['saw','see','seed'],0,'Irregular past: see → saw.','See has an irregular past.'],['Did you ___ the tour?',['enjoyed','enjoy','enjoying'],1,'After did use base verb.','Did + enjoy'],['I did not ___ a car.',['rented','rent','renting'],1,'Did not + base verb.','After did not…']])}${openTask('guideSpeak','Speak to a local guide','Ask about opening hours, entrance fees and guided visits. Then explain why you chose this attraction.','What time does the museum open? How much is the ticket?','Could you tell me whether guided visits are available, what the entrance fee includes and which activities you would recommend for someone interested in local heritage?','Use Could you tell me…? and I am interested in…')}`);html+=section('review','08','Your complete Windhoek mission','Use everything you have learned: dates, future plans, airport questions, transfers, hotel reception and sightseeing.',`<div class="panel"><h3>Trip summary</h3><div id="summary" class="output">Complete the travel planner in the earlier chapters to build your summary.</div><div class="actions"><button id="summaryBtn">Update my journey</button><button id="copySummary">Copy summary</button><button id="download">Download my notes</button></div></div>${practice('Final challenge · mixed English',[['An intention: I ___ visit Windhoek.',['am going to','am visited','have go'],0,'Going to + base verb describes an intention.','Use going to'],['A fixed arrangement: We ___ on Tuesday.',['are flying','flew yesterday','are fly'],0,'Present continuous can describe fixed future arrangements.','are + -ing'],['A timetable: The bus ___ at six.',['leave','leaves','leaving'],1,'Present simple for timetables.','Third-person -s'],['A polite request: ___ you help me?',['Could','Could to','Do could'],0,'Could + base verb.','Could…?'],['Right now: We ___ for our taxi.',['wait yesterday','are waiting','waiting are'],1,'Present continuous for an action now.','are + -ing'],['A finished visit: I ___ the museum yesterday.',['have visit','visited','am visit'],1,'Past simple with yesterday.','Finished past time']])}${stage('FINAL','Role reversal · live travel simulation','The trainer plays each airport or hotel employee. You answer as the passenger. If you get stuck, open the model dialogue and try again.',`${modelDialog('The complete trip in ten exchanges',[['Travel agent','What are you going to do in Windhoek?'],['You','I am going to explore local culture and wildlife conservation.'],['Travel agent','When are you flying?'],['You','I am flying on Friday morning. My flight is confirmed.'],['Check-in agent','Do you have any checked luggage?'],['You','Yes, I am checking in one suitcase.'],['Security officer','Please follow the security instructions.'],['You','Of course. Should I take out my laptop?'],['Gate agent','Please show your boarding pass.'],['You','Here it is. Is boarding starting now?'],['Immigration officer','What is the purpose of your visit?'],['You','I am visiting Namibia for a holiday.'],['Baggage agent','Can I help you?'],['You','I cannot find my suitcase. Could you help me?'],['Customs staff','Please follow the customs signs.'],['You','Thank you. Where is the arrivals exit?'],['Driver','Where are you going?'],['You','To my hotel in Windhoek. Could you confirm the fare?'],['Receptionist','Welcome. Do you have a reservation?'],['You','Yes. I have a booking under my name. Is breakfast included?'],['Local guide','What interests you about Windhoek?'],['You','I am particularly interested in nature and conservation.']])}${openTask('fullJourney','Write the complete travel story · 8 stages','Write a short story in chronological order: (1) plans, (2) confirmed flight, (3) check-in, (4) security, (5) boarding, (6) passport and baggage, (7) customs and transfer, (8) hotel and sightseeing. Include two polite questions.','I am going to visit Windhoek. I am flying on Friday. First, I check in my bag, then I go through security and board. When I arrive, I show my passport, collect my suitcase and follow the customs signs. Then I take a taxi to my hotel. Could you confirm the fare? At the hotel, I ask: Is breakfast included?','I am planning a trip to Windhoek to learn about local culture and conservation. My flight is confirmed for Friday morning. At the airport, I check in my suitcase, complete security screening and go to the departure gate. After boarding and flying to Namibia, I follow the arrivals procedures, answer questions at passport control, collect my luggage and follow customs instructions. I then meet my pre-arranged driver and ask him to confirm our meeting point and estimated fare. At the hotel, I check in and enquire about breakfast. The following day, I am meeting a guide for a conservation visit.','Use first, next, then, after that, finally; going to / am flying / could you.')}`)}${openTask('finalSpeak','Your complete travel story','Tell your trainer your plan, your flight arrangements, how you will get to your hotel and what you want to visit. Include at least one polite question.','I am going to visit Windhoek. I am flying from France. Could you help me find my hotel?','I am planning a visit to Windhoek, and I am arranging my flights and accommodation. Once I arrive, I would like to explore the city’s cultural sites and learn more about wildlife conservation. Could you recommend a suitable guided visit?','Use going to, present continuous for an arrangement and Could you…?')}<div class="panel"><h3>Lesson notes</h3><label>What I learned<textarea id="learned"></textarea></label><label>What I want to practise next<textarea id="next"></textarea></label><label>Lesson link<input id="lessonLink" placeholder="Paste your lesson URL"></label><label>Trainer notes<textarea id="trainerNotes"></textarea></label></div>`);html+=section('pronunciation','09','Pronunciation clinic · -ed and final -s','Learn to hear and pronounce the endings clearly. Use the Listen buttons, repeat aloud, then check each answer.',`${explainMini('Past simple: three pronunciations of -ed','The written -ed ending has THREE pronunciations. Listen to the LAST SOUND of the verb, not its last letter.','/t/ after voiceless sounds except /t/: walked, watched, helped; /d/ after voiced sounds except /d/: travelled, explored, planned; /ɪd/ after /t/ or /d/: visited, wanted, needed.','Do not add an extra syllable to walked or planned.','Did you visit Etosha? Did you watch the animals?','The spelling -ed stays the same, but the pronunciation changes. travelled is two syllables in British English; visited has three.')}${languageBox('Past tense · listen and repeat',[['walked /t/','a marché','We walked in the desert.'],['watched /t/','a observé','We watched the animals.'],['travelled /d/','a voyagé','We travelled to Namibia.'],['explored /d/','a exploré','We explored the coast.'],['visited /ɪd/','a visité','We visited Etosha.'],['protected /ɪd/','a protégé','The rangers protected the animals.']])}${practice('Past tense endings · immediate feedback',[['What is the final sound in walked?',['/ɪd/','/t/','/d/'],1,'Walked ends in /t/; no extra syllable.','The /k/ sound is voiceless.'],['What is the ending in travelled?',['/d/','/ɪd/','/t/'],0,'Travelled ends in /d/.','The /l/ sound is voiced.'],['How does visited end?',['/t/','/d/','/ɪd/'],2,'Visited ends in /ɪd/, adding a syllable.','The base verb visit ends in /t/.'],['Which verb has an extra syllable?',['watched','planned','wanted'],2,'Wanted ends in /ɪd/.','The base verb want ends in /t/.']])}${explainMini('Final -s: three pronunciations','The final -s appears in plural nouns, third-person verbs and possessives. Pronounce it clearly: the ending can change the meaning.','/s/ after voiceless sounds: parks, elephants, stops; /z/ after voiced sounds: animals, guides, birds; /ɪz/ after sibilant sounds: buses, beaches, watches.','Do not omit the ending in two parks, three guides, or she watches.','Does she visit the parks? Are there many animals?','Adjectives do NOT take a plural -s: beautiful animals, not beautifuls animals. /ɪz/ adds a syllable.')}${languageBox('Final -s · listen and repeat',[['parks /s/','parcs','There are three parks.'],['elephants /s/','éléphants','We saw elephants.'],['animals /z/','animaux','The animals are protected.'],['guides /z/','guides','The guides explain the rules.'],['beaches /ɪz/','plages','Namibia has beautiful beaches.'],['watches /ɪz/','observe','She watches wildlife.']])}${practice('Final -s · immediate feedback',[['How does parks end?',['/z/','/s/','/ɪz/'],1,'Parks ends with /s/ after /k/.','The /k/ sound is voiceless.'],['How does animals end?',['/ɪz/','/s/','/z/'],2,'Animals ends with /z/ after voiced /l/.','Feel the vibration in your throat.'],['How does beaches end?',['/ɪz/','/z/','/s/'],0,'Beaches adds an extra syllable /ɪz/.','The word beach ends with /tʃ/.'],['Choose the correct sentence.',['Two beautifuls parks','Two beautiful parks','Two beautiful park'],1,'Plural -s belongs on the noun, not the adjective.','Adjectives do not change for plural nouns.']])}${openTask('pronStory','Tell a past-tense travel story','Imagine you have returned from Namibia. Say what you visited, watched and explored. Clearly pronounce every -ed and plural -s.','I visited Etosha. I watched elephants and explored the parks.','During my journey, I visited Etosha National Park, watched wildlife at several waterholes and explored the dramatic desert landscapes. I also learned how rangers protect endangered animals.','Visited /ɪd/, watched /t/, explored /d/; parks /s/, animals /z/.')}`);html+=section('conservation','10','Wildlife protection · poaching and conservation','Use real-world environmental vocabulary to discuss causes, consequences and possible solutions.',`<div class="panel"><h3>🦏 Poaching = braconnage</h3><p><b>Poaching</b> means illegally hunting, capturing or killing wild animals. <b>Anti-poaching</b> means efforts to prevent it. Namibia has conservation initiatives involving protected areas, rangers and local communities. Rhinoceroses and elephants are among the animals affected by wildlife crime. The issue is complex: habitat protection, community livelihoods, law enforcement and responsible tourism all matter.</p><p><button data-speak="Poaching threatens wildlife. Rangers protect endangered species. Local communities can support conservation.">🔊 Listen and repeat</button></p></div>${languageBox('Conservation · key words',[['poaching','braconnage','Poaching threatens wildlife.'],['poacher','braconnier','A poacher hunts animals illegally.'],['ranger','garde de réserve','Rangers patrol protected areas.'],['endangered species','espèces menacées','Rhinos are endangered species.'],['habitat','habitat naturel','Animals need a safe habitat.'],['protect','protéger','We must protect wildlife.'],['conservation','protection de la nature','Conservation helps preserve biodiversity.'],['community','communauté','Local communities play an important role.']])}${practice('Conservation · test your vocabulary',[['What does poaching mean?',['Legal photography','Illegal hunting of wild animals','A guided walk'],1,'Poaching is illegal hunting or capture of wildlife.','Braconnage.'],['Who patrols and protects a reserve?',['Rangers','Passengers','Receptionists'],0,'Rangers help protect protected areas.','Think of wildlife guards.'],['Choose the correct past-tense sentence.',['Rangers protected rhinos.','Rangers protecteded rhinos.','Rangers protecting rhinos yesterday.'],0,'Protected ends in /ɪd/; the past tense is protected.','After /t/, -ed sounds /ɪd/.']])}${modelDialog('At the travel agency · conservation visit',[['Travel agent','Would you like to include a wildlife conservation experience in your itinerary?'],['You','Yes. I am particularly interested in protecting endangered species.'],['Travel agent','Would you like to learn about anti-poaching programmes?'],['You','Absolutely. How do local rangers and communities help protect rhinos?'],['Travel agent','We can look for responsible educational visits and check their availability.'],['You','That sounds fascinating. Could you explain the cost and the best season to visit?']])}${openTask('conserveTalk','Express your opinion about poaching','Explain why protecting wildlife matters and suggest two ways to help. Practise the final -s in animals and rangers.','Poaching is dangerous for animals. Rangers protect wildlife.','I believe that poaching threatens biodiversity and local communities. Governments, conservation organisations and local residents can work together to protect habitats, support rangers and encourage responsible tourism.','I believe… because…; We should…; Rangers protect…')}`);$('sections').innerHTML=html;function persist(){const data={results};document.querySelectorAll('input,select,textarea').forEach(el=>{if(el.id)data[el.id]=el.type==='checkbox'?el.checked:el.value});localStorage.setItem(S,JSON.stringify(data))}document.querySelectorAll('input,select,textarea').forEach(el=>{if(saved[el.id]!==undefined){if(el.type==='checkbox')el.checked=!!saved[el.id];else el.value=saved[el.id]}el.addEventListener('input',persist);el.addEventListener('change',persist)});function speak(str){if(!('speechSynthesis' in window)){alert('Speech synthesis is not available in this browser.');return}speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(str);u.lang=$('accent').value;u.rate=.85;let voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang.toLowerCase()===u.lang.toLowerCase())||null;speechSynthesis.speak(u)}function status(){let v=Object.values(results);let correct=v.filter(x=>x.ok).length;$('score').textContent=`Exercises: ${correct} correct / ${v.length} attempted`;$('bottomScore').textContent=`${correct} correct answers`;}function mark(box,id){let r=results[id];if(!r)return;box.querySelectorAll('[data-choice]').forEach(b=>{b.classList.remove('correct','wrong');if(+b.dataset.choice===r.choice)b.classList.add(r.ok?'correct':'wrong')});let f=box.querySelector('.feedback');f.className='feedback '+(r.ok?'good':'bad');f.textContent=(r.ok?'✓ Correct! ':'✗ Try again. ')+exercises[id].explain;}document.querySelectorAll('[data-quiz]').forEach(b=>mark(b,b.dataset.quiz));status();function niceDate(s){if(!s)return '[date]';return new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'long',year:'numeric',weekday:'long',timeZone:'UTC'}).format(new Date(s+'T12:00:00Z'))}function summary(){return `MY NAMIBIA JOURNEY\nDeparture: ${niceDate($('depart').value)}\nReturn: ${niceDate($('return').value)}\nTravellers: ${$('travellers').value}\nDeparture airport: ${$('origin').value}\nArrival: Jomo Namibiatta International Airport (WDH)\nFlight preference: ${$('flight').value}\nAccommodation: ${$('stay').value} · ${$('area').value}\nTransport: ${$('transfer').value}\nMain interest: ${$('priority').value}\nFirst attraction: ${$('attraction').value}\n\nMy English: I am going to visit Windhoek. I would like to discover ${$('attraction').value}. Could you help me plan my journey?`}document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.speak){speak(decodeURIComponent(b.dataset.speak));return}if(b.dataset.speakfield){speak($(b.dataset.speakfield).value||$(b.dataset.speakfield).textContent);return}if(b.dataset.choice!==undefined){let q=b.closest('[data-quiz]'),id=q.dataset.quiz,choice=+b.dataset.choice;results[id]={choice,ok:choice===exercises[id].correct};mark(q,id);persist();status();return}if(b.dataset.hint){let id=b.dataset.hint,f=b.closest('.quiz').querySelector('.feedback');f.className='feedback';f.textContent='Hint: '+exercises[id].hint;return}if(b.dataset.answer){let id=b.dataset.answer,q=b.closest('.quiz'),answer=q.querySelector('[data-choice="'+exercises[id].correct+'"]');q.querySelectorAll('[data-choice]').forEach(x=>x.classList.toggle('correct',x===answer));let f=q.querySelector('.feedback');f.className='feedback good';f.textContent='✓ Model answer: '+answer.textContent+'. '+exercises[id].explain;return}if(b.dataset.retry){let id=b.dataset.retry,box=b.closest('.quiz');delete results[id];box.querySelectorAll('[data-choice]').forEach(x=>x.classList.remove('correct','wrong'));box.querySelector('.feedback').textContent='';persist();status();return}if(b.dataset.model){$(b.dataset.model+'Models').classList.toggle('show');return}if(b.dataset.openhint){let f=$(b.dataset.openhint+'Feedback');f.className='feedback';f.textContent='Hint: '+b.dataset.msg;return}if(b.dataset.open){let id=b.dataset.open,t=$(id).value.trim(),f=$(id+'Feedback'),ok=t.split(/\s+/).filter(Boolean).length>=12;f.className='feedback '+(ok?'good':'bad');f.textContent=ok?'✓ You have enough detail to practise. Compare with the models. Open responses require trainer review for full correctness.':'Add a few more details and at least one complete sentence (about 12 words).';return}});$('datesBtn').onclick=()=>{let a=$('depart').value,b=$('return').value;if(!a||!b||b<=a){$('dateOutput').textContent='Please select valid departure and return dates.';return}let days=Math.round((new Date(b)-new Date(a))/86400000);$('dateOutput').textContent=`I am going to leave France on ${niceDate(a)}. I am going to return on ${niceDate(b)}. I am going to stay for ${days} nights. My preferred departure time is ${$('time').value}.`;persist()};$('planBtn').onclick=()=>{$('planOutput').textContent=`I am going to travel from ${$('origin').value} to Windhoek (WDH). I would like to compare flights: ${$('flight').value.toLowerCase()}. I am looking for a ${$('stay').value.toLowerCase()}. My priority is ${$('priority').value.toLowerCase()}.`;persist()};$('transferBtn').onclick=()=>{$('transferOutput').textContent=`I am going to take a ${$('transfer').value.toLowerCase()} from the airport. Could you tell me the fare and how long the journey takes?`;persist()};$('hotelBtn').onclick=()=>{let a=$('depart').value||'[arrival date]',b=$('return').value||'[departure date]';$('hotelOutput').textContent=`Subject: Accommodation enquiry — Windhoek\n\nDear Reservations Team,\nI am planning a visit to Windhoek from ${a} to ${b} for ${$('travellers').value} traveller(s). I would like to enquire about a ${$('room').value.toLowerCase()} in the ${$('area').value} area. My preference is: ${$('breakfast').value.toLowerCase()}. ${$('request').value?'Additional request: '+$('request').value+'.':''}\nCould you confirm the total rate, taxes, cancellation conditions and airport transfer options?\nThank you for your help.\nKind regards,\nFrançoise`;persist()};$('attractionBtn').onclick=()=>{$('attractionOutput').textContent=`I am going to visit ${$('attraction').value}. Could you tell me the opening hours, entrance fee and whether a guided tour is available? I would like to learn more about Namibia.`;persist()};$('summaryBtn').onclick=()=>{$('summary').textContent=summary();persist()};function copy(t){if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(t).then(()=>alert('Copied!')).catch(()=>prompt('Copy this text:',t))}else prompt('Copy this text:',t)} $('copySummary').onclick=()=>copy(summary());$('copyEnquiry').onclick=()=>copy($('hotelOutput').textContent);$('download').onclick=()=>{let notes=summary()+'\n\nMY RESPONSES\n'+[...document.querySelectorAll('textarea')].map(x=>x.id+': '+x.value).join('\n\n');let blob=new Blob([notes],{type:'text/plain;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Francoise_Windhoek_Lesson_Notes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('print').onclick=()=>window.print();$('reset').onclick=()=>{if(confirm('Reset all lesson answers and scores?')){localStorage.removeItem(S);location.reload()}};$('french').addEventListener('change',()=>document.body.classList.toggle('hidefr',!$('french').checked));document.body.classList.toggle('hidefr',!$('french').checked);
